runner_source:
param([Parameter(Mandatory=$true)][string]$TestExecutable)
$ErrorActionPreference = 'Stop'
$repo = (Resolve-Path (Join-Path $PSScriptRoot '../..')).Path
Set-Location -LiteralPath $repo
function Digest($path) { (Get-FileHash -LiteralPath $path -Algorithm SHA256).Hash.ToLowerInvariant() }
function Save-Json($path, $value) { [IO.File]::WriteAllText($path, ($value | ConvertTo-Json -Depth 100) + "`n") }
function Source-Manifest {
    @(git -C $repo ls-files src tools examples Cargo.toml Cargo.lock rust-toolchain.toml | ForEach-Object {
        [ordered]@{ path = $_; sha256 = Digest (Join-Path $repo $_) }
    })
}
$sourceFiles = Source-Manifest
$sourceJson = $sourceFiles | ConvertTo-Json -Depth 5 -Compress
$manifestPath = Join-Path $repo 'tests/baseline/manifest.json'
$manifest = Get-Content -LiteralPath $manifestPath -Raw | ConvertFrom-Json
$models = (Resolve-Path (Join-Path $repo '../SimdPaddleOCR/models')).Path
$assetHashes = @()
foreach ($asset in $manifest.assets) {
    $digest = Digest (Join-Path $models $asset.file)
    if ($digest -ne $asset.sha256 -and $digest -ne $asset.sha256_crlf) { throw "Model mismatch: $($asset.file)" }
    $assetHashes += [ordered]@{ file = $asset.file; sha256 = $digest }
}
$ordinaryExe = Join-Path $PSScriptRoot 'cpu_owner_probe.exe'
$profileExe = Join-Path $PSScriptRoot 'cpu_profile.exe'
$TestExecutable = (Resolve-Path -LiteralPath $TestExecutable).Path
$executables = @($ordinaryExe, $profileExe, $TestExecutable) | ForEach-Object {
    [ordered]@{ path = $_; sha256 = Digest $_ }
}
$script:spent = 0.0
$script:execution = @()
function Run-Bounded($kind, $model, $fixture, $exe, $arguments, $limitMs) {
    $remaining = 60.0 - $script:spent
    if ($remaining -lt 1) { throw '60-second total performance execution budget exhausted' }
    $timeoutMs = [int][Math]::Min($limitMs, [Math]::Floor(1000 * $remaining))
    $stem = Join-Path $PSScriptRoot ($kind + '-' + $model + '-' + $fixture)
    if (Test-Path -LiteralPath "$stem.json") { throw "Refuse to overwrite prior measurement: $stem" }
    if (Test-Path -LiteralPath "$stem.txt") { throw "Refuse to overwrite prior measurement: $stem" }
    $json = $kind -in @('ordinary','profile')
    $output = $stem + $(if ($json) { '.json' } else { '.txt' })
    $timer = [Diagnostics.Stopwatch]::StartNew()
    $process = Start-Process -FilePath $exe -ArgumentList $arguments -WindowStyle Hidden -RedirectStandardOutput $output -RedirectStandardError "$stem.log" -PassThru
    $exited = $process.WaitForExit($timeoutMs)
    if (-not $exited) { Stop-Process -Id $process.Id -Force }
    $process.WaitForExit()
    $timer.Stop()
    $script:spent += $timer.Elapsed.TotalSeconds
    $record = [ordered]@{
        kind = $kind; model = $model; fixture = $fixture; executable_sha256 = Digest $exe
        arguments = $arguments; timeout_ms = $timeoutMs; wall_seconds = $timer.Elapsed.TotalSeconds
        exited_before_timeout = $exited; exit_code = $process.ExitCode
        stderr = [IO.File]::ReadAllText("$stem.log")
    }
    if ($json -and $exited -and $process.ExitCode -eq 0) {
        $record.measurement = Get-Content -LiteralPath $output -Raw | ConvertFrom-Json
        if (-not $record.measurement.complete_owned_outputs_exactly_equal) { throw "Missing output parity: $stem" }
    } else { $record.raw_output = [IO.File]::ReadAllText($output) }
    $script:execution += $record
    Save-Json (Join-Path $PSScriptRoot 'execution-ledger.json') ([ordered]@{seconds=$script:spent; execution=$script:execution})
    if (-not $exited -or $process.ExitCode -ne 0) { throw "Failed or timed out: $stem" }
    Write-Output "$kind $model $fixture : $($timer.Elapsed.TotalSeconds.ToString('F3')) s"
}
$cases = @(
    @('tiny','imgs_1'), @('tiny','imgs_00018069'), @('tiny','imgs_00006737'),
    @('small','imgs_00018069'), @('medium','imgs_00018069')
)
foreach ($case in $cases) {
    Run-Bounded 'ordinary' $case[0] $case[1] $ordinaryExe @($case[0],$case[1],'0','1') 10000
    Run-Bounded 'profile' $case[0] $case[1] $profileExe @($case[0],$case[1],'24','0') 10000
    if ($script:execution[-2].measurement.control_output_sha256 -ne $script:execution[-1].measurement.control_output_sha256) {
        throw "Profile/unprofiled complete output digest mismatch: $case"
    }
}
# Different, explicitly isolated diagnostic configurations: real sparse DET at
# eight logical CPUs and synthetic REC feature prefixes at one logical CPU.
# These localize physical operators; never pool them with the CPU24 page data.
Run-Bounded 'operators' 'det-all' 'imgs_1' $TestExecutable @('runtime::optimized::tests::performance::sparse_detector_production_steps','--exact','--ignored','--nocapture','--test-threads=1') 15000
Run-Bounded 'operators' 'rec-small-medium' 'synthetic' $TestExecutable @('runtime::optimized::tests::performance::recognition_backbone_physical_steps','--exact','--ignored','--nocapture','--test-threads=1') 10000
foreach ($record in $script:execution | Where-Object kind -eq 'operators') {
    if ($record.raw_output -notmatch 'test result: ok\. 1 passed') { throw 'Operator diagnostic did not execute exactly one test' }
}
if ($sourceJson -ne ((Source-Manifest) | ConvertTo-Json -Depth 5 -Compress)) { throw 'Source changed during measurement' }
foreach ($exe in $executables) { if ($exe.sha256 -ne (Digest $exe.path)) { throw 'Executable changed during measurement' } }
$evidence = [ordered]@{
    schema_version = 1; date = '2026-10-18'; timezone = 'Asia/Shanghai'; timestamp = (Get-Date).ToString('o')
    git_head = (git -C $repo rev-parse HEAD).Trim(); source_files = $sourceFiles
    source_stable_during_measurement = $true; executables = $executables
    production_diff = (git -C $repo diff -- src examples tools Cargo.toml Cargo.lock | Out-String)
    manifest_sha256 = Digest $manifestPath; assets = $assetHashes
    cpu = @(Get-CimInstance Win32_Processor | Select-Object Name,NumberOfCores,NumberOfLogicalProcessors)
    system = (Get-CimInstance Win32_ComputerSystem | Select-Object Manufacturer,Model,TotalPhysicalMemory)
    power_scheme = (powercfg /getactivescheme | Out-String)
    build_environment = [ordered]@{RUSTFLAGS=$env:RUSTFLAGS; CARGO_ENCODED_RUSTFLAGS=$env:CARGO_ENCODED_RUSTFLAGS; CARGO_BUILD_TARGET=$env:CARGO_BUILD_TARGET}
    rustc = (rustc -Vv | Out-String); manifest_settings = $manifest.settings
    fixtures = @($manifest.fixtures | Where-Object { $_.id -in @('imgs_1','imgs_00018069','imgs_00006737') })
    page_settings = [ordered]@{cpu_context_capacity=24; affinity='ffffff'; concurrency=1; line_workers=0; recognition_batch_size=1; alignment=$false; detector_preprocess_cap=16}
    ordinary_runs = [ordered]@{cases=5; warmups_per_case=1; measured_per_case=3; includes_owned_conversion=$true; instrumentation=$false}
    profile_runs = [ordered]@{cases=5; warmups_per_case=1; measured_per_case=1; includes_owned_conversion=$false; instrumentation=$true}
    operator_runs = [ordered]@{detector_graphs=3; detector_threads=8; recognition_prefixes=2; recognition_threads=1; warmups_per_graph=1; measured_per_graph=1; instrumentation=$true}
    complete_profile_and_ordinary_output_digests_match = $true
    total_inference_calls = 40; execution_budget_seconds = 60; total_performance_execution_seconds = $script:spent
    execution = $script:execution
    correctness = 'Before timing: cargo test --release --locked --features profiling --lib profile::tests. See validation log in this report. Every measured page equals its complete warm-up output, and profiling/unprofiled output digests match. Each physical operator diagnostic asserts output-bit equality against its warm-up.'
    validation_log = [IO.File]::ReadAllText((Join-Path $PSScriptRoot 'validation.txt'))
    limitations = 'Local physical Windows host; no CI, VM or remote execution. Three source images, five page/model cases, one CPU24 page configuration. Profiles and graph diagnostics are single samples. Operator thread configurations differ from page runs and must not be pooled. Excludes image I/O/decode, capture, external queueing, alignment and serialization. No ground-truth accuracy qualification, hardware counters or concurrent-throughput measurement. Windows owner thread_cpu_ns is unavailable; owner wall time includes waits.'
    runner_source = [IO.File]::ReadAllText($PSCommandPath)
    ordinary_build_log = [IO.File]::ReadAllText((Join-Path $PSScriptRoot 'build-ordinary.log'))
    profile_build_log = [IO.File]::ReadAllText((Join-Path $PSScriptRoot 'build-profile.log'))
}
Save-Json (Join-Path $PSScriptRoot 'evidence.json') $evidence
Write-Output "Total bounded performance execution: $($script:spent.ToString('F3')) s"
